            writer.WriteString("rate_type", rateTypeRawValue);
            if (editCreditPayload.HierarchyConfigurationOption.IsSet)
            {
                writer.WritePropertyName("hierarchy_configuration");
                JsonSerializer.Serialize(writer, editCreditPayload.HierarchyConfiguration, jsonSerializerOptions);
            }
        }
    }
}
